  \/ (exists mb ms, (a_live st) !! p = Some (CSec mb ms n) /\ A = mb + SEC_UOFF /\ sec_wf1 L (CSec mb ms n) /\ is_primary n = false
      /\ In (CSec mb ms n) (sec_chunks_of st)).
